def preserve_legacy_outcomes(apps, schema_editor):
    """Never automatically resend a B26 job whose prior outcome is uncertain."""
    delivery = apps.get_model("workflow", "EmailDelivery")
    attempt = apps.get_model("workflow", "EmailAttempt")
    alias = schema_editor.connection.alias
    now = django.utils.timezone.now()
    for job in delivery.objects.using(alias).all().iterator():
        if job.status == "PENDING":
            job.failure_code = ""
            job.save(using=alias, update_fields=["failure_code"])
            continue
        job.next_attempt_at = None
        job.failure_code = ""
        if job.status in ("SENT", "FAILED", "SENDING"):
            job.attempt_count = 1
            outcome = {"SENT": "SENT", "FAILED": "FAILED", "SENDING": "UNKNOWN"}[job.status]
            code = {"SENT": "", "FAILED": "legacy_failure", "SENDING": "delivery_unknown"}[job.status]
            attempt.objects.using(alias).create(
                delivery_id=job.pk, number=1, status=outcome,
                started_at=job.started_at or job.created_at,
                lease_expires_at=job.started_at or job.created_at,
                finished_at=job.sent_at or now, diagnostic_code=code,
            )
            if job.status == "SENDING":
                job.status = "FAILED"
            job.failure_code = code
        job.save(using=alias, update_fields=["next_attempt_at", "attempt_count", "status", "failure_code"])


